package com.mycompany.sistemaoptica.web;

import com.mycompany.sistemaoptica.config.PasswordUtil;
import jakarta.servlet.http.HttpSession;
import java.math.BigDecimal;
import java.sql.SQLException;
import java.util.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class WebController {
    private final Db db;
    public WebController(Db db){this.db=db;}
    @ModelAttribute public void commonAttributes(HttpSession session, Model model) {
        model.addAttribute("role", role(session));
        model.addAttribute("name", session.getAttribute("name"));
        model.addAttribute("logged", logged(session));
    }
    private boolean logged(HttpSession s){return s.getAttribute("uid")!=null;}
    private String role(HttpSession s){return Objects.toString(s.getAttribute("role"),"");}
    private boolean vendor(HttpSession s){return "VENDEDOR".equalsIgnoreCase(role(s));}
    private boolean client(HttpSession s){return "CLIENTE".equalsIgnoreCase(role(s));}
    private int uid(HttpSession s){return s.getAttribute("uid") instanceof Number n?n.intValue():-1;}
    private int clientId(HttpSession s)throws SQLException {
        if(s.getAttribute("clientId") instanceof Number n)return n.intValue();
        List<Map<String,Object>> r=db.query("SELECT id_cliente FROM Clientes WHERE id_usuario=?",uid(s));
        int id=r.isEmpty()?-1:((Number)r.get(0).get("id_cliente")).intValue(); s.setAttribute("clientId",id); return id;
    }
    private String requireLogin(HttpSession s, RedirectAttributes ra){if(!logged(s)){ra.addFlashAttribute("error","Iniciá sesión para continuar.");return "redirect:/login";}return null;}
    private String requireVendor(HttpSession s, RedirectAttributes ra){String a=requireLogin(s,ra);if(a!=null)return a;if(!vendor(s)){ra.addFlashAttribute("error","Esta sección es solo para vendedores.");return "redirect:/";}return null;}
    @GetMapping({"/","/inicio"}) public String home(HttpSession s, Model m){m.addAttribute("logged",logged(s));m.addAttribute("role",role(s));m.addAttribute("name",s.getAttribute("name"));return logged(s)?"dashboard":"home";}
    @GetMapping("/login") public String login(){return "login";}
    @PostMapping("/login") public String doLogin(@RequestParam String correo,@RequestParam String contrasena,HttpSession s,RedirectAttributes ra){
        try {var rows=db.query("SELECT id_usuario, usuario, correo, contrasena, rol, estado FROM Usuarios WHERE correo=?",correo.trim());
            if(rows.isEmpty()){ra.addFlashAttribute("error","Correo o contraseña incorrectos.");return "redirect:/login";}
            var u=rows.get(0); String state=Objects.toString(u.get("estado"),""); String hash=Objects.toString(u.get("contrasena"),""); String r=Objects.toString(u.get("rol"),"");
            if(!"ACTIVO".equalsIgnoreCase(state)||!PasswordUtil.verificarPassword(contrasena,hash)||!(r.equalsIgnoreCase("CLIENTE")||r.equalsIgnoreCase("VENDEDOR"))){ra.addFlashAttribute("error","Credenciales incorrectas o cuenta inactiva.");return "redirect:/login";}
            s.setAttribute("uid",((Number)u.get("id_usuario")).intValue());s.setAttribute("role",r.toUpperCase());s.setAttribute("name",Objects.toString(u.get("usuario"),correo));s.removeAttribute("clientId");return "redirect:/";
        }catch(Exception e){ra.addFlashAttribute("error","No se pudo conectar con la base de datos. Verificá las variables TURSO.");return "redirect:/login";}}
    @GetMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/login";}
    @GetMapping("/registro") public String register(){return "registro";}
    @PostMapping("/registro") public String registerPost(@RequestParam String nombre,@RequestParam String dni,@RequestParam String telefono,@RequestParam String correo,@RequestParam String contrasena,RedirectAttributes ra){
        if(nombre.isBlank()||dni.isBlank()||correo.isBlank()||contrasena.length()<8){ra.addFlashAttribute("error","Completá los campos y usá una contraseña de al menos 8 caracteres.");return "redirect:/registro";}
        try {if(!db.query("SELECT id_usuario FROM Usuarios WHERE correo=?",correo.trim()).isEmpty()){ra.addFlashAttribute("error","Ese correo ya está registrado.");return "redirect:/registro";}
            int iu=db.nextId("Usuarios","id_usuario"), ic=db.nextId("Clientes","id_cliente");
            db.execute("INSERT INTO Usuarios (id_usuario,usuario,correo,contrasena,rol,estado) VALUES (?,?,?,?,?,?)",iu,correo.trim(),correo.trim(),PasswordUtil.hashPassword(contrasena),"CLIENTE","ACTIVO");
            db.execute("INSERT INTO Clientes (id_cliente,id_usuario,nombre,dni,telefono) VALUES (?,?,?,?,?)",ic,iu,nombre.trim(),dni.trim(),telefono.trim());
            ra.addFlashAttribute("ok","Cuenta creada. Ya podés iniciar sesión.");return "redirect:/login";
        }catch(Exception e){ra.addFlashAttribute("error","No se pudo registrar: "+safe(e));return "redirect:/registro";}}
    @GetMapping("/productos") public String products(HttpSession s,Model m,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{m.addAttribute("items",db.query("SELECT * FROM Productos ORDER BY id_producto"));}catch(Exception e){m.addAttribute("error",safe(e));}return "productos";}
    @PostMapping("/productos/guardar") public String saveProduct(HttpSession s,@RequestParam(required=false) Integer id_producto,@RequestParam String nombre,@RequestParam String tipo,@RequestParam(required=false) String marca,@RequestParam(required=false) String material,@RequestParam(required=false) String forma,@RequestParam BigDecimal precio,@RequestParam int stock,@RequestParam(defaultValue="ACTIVO") String estado,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{if(id_producto==null)db.execute("INSERT INTO Productos (nombre,tipo,marca,material,forma,precio,stock,estado) VALUES (?,?,?,?,?,?,?,?)",nombre,tipo,marca,material,forma,precio,stock,estado);else db.execute("UPDATE Productos SET nombre=?,tipo=?,marca=?,material=?,forma=?,precio=?,stock=?,estado=? WHERE id_producto=?",nombre,tipo,marca,material,forma,precio,stock,estado,id_producto);ra.addFlashAttribute("ok","Producto guardado.");}catch(Exception e){ra.addFlashAttribute("error","No se pudo guardar: "+safe(e));}return "redirect:/productos";}
    @PostMapping("/productos/eliminar") public String deleteProduct(HttpSession s,@RequestParam int id,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{db.execute("DELETE FROM Productos WHERE id_producto=?",id);ra.addFlashAttribute("ok","Producto eliminado.");}catch(Exception e){ra.addFlashAttribute("error","No se pudo eliminar: "+safe(e));}return "redirect:/productos";}
    @GetMapping("/clientes") public String clients(HttpSession s,Model m,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{m.addAttribute("items",db.query("SELECT c.id_cliente,c.id_usuario,c.nombre,c.dni,c.telefono,u.correo FROM Clientes c JOIN Usuarios u ON u.id_usuario=c.id_usuario ORDER BY c.id_cliente"));}catch(Exception e){m.addAttribute("error",safe(e));}return "clientes";}
    @GetMapping("/mediciones") public String measurements(HttpSession s,Model m,RedirectAttributes ra){String a=requireLogin(s,ra);if(a!=null)return a;try{int cid=client(s)?clientId(s):-1;if(vendor(s)){m.addAttribute("clientes",db.query("SELECT id_cliente,nombre FROM Clientes ORDER BY nombre"));m.addAttribute("items",db.query("SELECT m.*,c.nombre FROM Mediciones m JOIN Clientes c ON c.id_cliente=m.id_cliente ORDER BY m.fecha DESC"));}else m.addAttribute("items",db.query("SELECT * FROM Mediciones WHERE id_cliente=? ORDER BY fecha DESC",cid));}catch(Exception e){m.addAttribute("error",safe(e));}return "mediciones";}
    @PostMapping("/mediciones/guardar") public String saveMeasurement(HttpSession s,@RequestParam(required=false) Integer id_cliente,@RequestParam(required=false) Double esfera,@RequestParam(required=false) Double cilindro,@RequestParam(required=false) Integer eje,@RequestParam(required=false) Double adicion,@RequestParam(required=false) String observaciones,RedirectAttributes ra){String a=requireLogin(s,ra);if(a!=null)return a;try{int cid=client(s)?clientId(s):Objects.requireNonNullElse(id_cliente,-1);if(cid<=0||(!vendor(s)&&!client(s)))throw new SQLException("Cliente no válido.");db.execute("INSERT INTO Mediciones (id_cliente,esfera,cilindro,eje,adicion,observaciones) VALUES (?,?,?,?,?,?)",cid,esfera,cilindro,eje,adicion,observaciones);ra.addFlashAttribute("ok","Medición registrada.");}catch(Exception e){ra.addFlashAttribute("error","No se pudo guardar la medición: "+safe(e));}return "redirect:/mediciones";}
    @GetMapping("/catalogo") public String catalog(HttpSession s,Model m,RedirectAttributes ra,@RequestParam(required=false) String marca,@RequestParam(required=false) String material,@RequestParam(required=false) String forma,@RequestParam(required=false) BigDecimal min,@RequestParam(required=false) BigDecimal max){String a=requireLogin(s,ra);if(a!=null)return a;try{String sql="SELECT * FROM Productos WHERE tipo='ARO' AND estado='ACTIVO' AND stock>0";List<Object> p=new ArrayList<>();if(marca!=null&&!marca.isBlank()){sql+=" AND marca=?";p.add(marca);}if(material!=null&&!material.isBlank()){sql+=" AND material=?";p.add(material);}if(forma!=null&&!forma.isBlank()){sql+=" AND forma=?";p.add(forma);}if(min!=null){sql+=" AND precio>=?";p.add(min);}if(max!=null){sql+=" AND precio<=?";p.add(max);}sql+=" ORDER BY nombre";m.addAttribute("items",db.query(sql,p.toArray()));m.addAttribute("marcas",db.query("SELECT DISTINCT marca FROM Productos WHERE tipo='ARO' AND marca IS NOT NULL ORDER BY marca"));m.addAttribute("materiales",db.query("SELECT DISTINCT material FROM Productos WHERE tipo='ARO' AND material IS NOT NULL ORDER BY material"));m.addAttribute("formas",db.query("SELECT DISTINCT forma FROM Productos WHERE tipo='ARO' AND forma IS NOT NULL ORDER BY forma"));if(client(s))m.addAttribute("apartados",db.query("SELECT a.*,p.nombre,p.marca FROM Apartados a JOIN Productos p ON p.id_producto=a.id_producto WHERE a.id_cliente=? ORDER BY a.fecha DESC",clientId(s)));}catch(Exception e){m.addAttribute("error",safe(e));}return "catalogo";}
    @PostMapping("/catalogo/apartar") public String apartar(HttpSession s,@RequestParam int id_producto,RedirectAttributes ra){String a=requireLogin(s,ra);if(a!=null)return a;if(!client(s)){ra.addFlashAttribute("error","Solo los clientes pueden apartar aros.");return "redirect:/catalogo";}try{int cid=clientId(s);var valid=db.query("SELECT id_producto FROM Productos WHERE id_producto=? AND tipo='ARO' AND estado='ACTIVO' AND stock>0",id_producto);if(valid.isEmpty())throw new SQLException("El aro ya no está disponible.");db.execute("INSERT INTO Apartados (id_cliente,id_producto,estado) VALUES (?,?,?)",cid,id_producto,"PENDIENTE");ra.addFlashAttribute("ok","Aro apartado correctamente.");}catch(Exception e){ra.addFlashAttribute("error","No se pudo apartar: "+safe(e));}return "redirect:/catalogo";}
    @GetMapping("/ventas") public String sales(HttpSession s,Model m,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{m.addAttribute("clientes",db.query("SELECT id_cliente,nombre FROM Clientes ORDER BY nombre"));m.addAttribute("productos",db.query("SELECT id_producto,nombre,precio,stock FROM Productos WHERE estado='ACTIVO' AND stock>0 ORDER BY nombre"));m.addAttribute("mediciones",db.query("SELECT m.id_medicion,m.id_cliente,c.nombre,m.fecha FROM Mediciones m JOIN Clientes c ON c.id_cliente=m.id_cliente ORDER BY m.fecha DESC"));m.addAttribute("items",db.query("SELECT v.*,c.nombre cliente FROM Ventas v JOIN Clientes c ON c.id_cliente=v.id_cliente ORDER BY v.fecha DESC LIMIT 50"));m.addAttribute("stockBajo",db.query("SELECT * FROM Productos WHERE tipo='ARO' AND stock<5 AND estado='ACTIVO' ORDER BY stock"));}catch(Exception e){m.addAttribute("error",safe(e));}return "ventas";}
    @PostMapping("/ventas/guardar") public String saveSale(HttpSession s,@RequestParam int id_cliente,@RequestParam int id_medicion,@RequestParam int id_producto,@RequestParam int cantidad,RedirectAttributes ra){String a=requireVendor(s,ra);if(a!=null)return a;try{if(cantidad<=0)throw new SQLException("La cantidad debe ser mayor que cero.");var valid=db.query("SELECT precio,stock FROM Productos WHERE id_producto=? AND estado='ACTIVO'",id_producto);if(valid.isEmpty())throw new SQLException("Producto no disponible.");int stock=((Number)valid.get(0).get("stock")).intValue();if(stock<cantidad)throw new SQLException("No hay suficiente stock.");var med=db.query("SELECT id_medicion FROM Mediciones WHERE id_medicion=? AND id_cliente=?",id_medicion,id_cliente);if(med.isEmpty())throw new SQLException("La medición no pertenece al cliente seleccionado.");BigDecimal unit=new BigDecimal(valid.get(0).get("precio").toString());BigDecimal subtotal=unit.multiply(BigDecimal.valueOf(cantidad));BigDecimal tax=subtotal.multiply(new BigDecimal("0.15")).setScale(2,java.math.RoundingMode.HALF_UP);BigDecimal total=subtotal.add(tax);int iv=db.nextId("Ventas","id_venta");db.execute("INSERT INTO Ventas (id_venta,id_cliente,id_vendedor,id_medicion,subtotal,impuesto,total) VALUES (?,?,?,?,?,?,?)",iv,id_cliente,uid(s),id_medicion,subtotal,tax,total);int idd=db.nextId("DetalleVenta","id_detalle");db.execute("INSERT INTO DetalleVenta (id_detalle,id_venta,id_producto,cantidad,precio_unitario,subtotal) VALUES (?,?,?,?,?,?)",idd,iv,id_producto,cantidad,unit,subtotal);db.execute("UPDATE Productos SET stock=stock-? WHERE id_producto=? AND stock>=?",cantidad,id_producto,cantidad);ra.addFlashAttribute("ok","Venta registrada. Número: "+iv+". Total: L. "+total);}catch(Exception e){ra.addFlashAttribute("error","No se pudo registrar la venta: "+safe(e));}return "redirect:/ventas";}
    private String safe(Exception e){String m=e.getMessage();if(m==null)return "Error inesperado.";return m.length()>180?m.substring(0,180):m;}
}
